function calculateCharge(order: any) {
  let result = 0;
  if (order.type === 'premium') {
    if (order.weight > 10) {
      result = order.weight * 5;
    } else {
      result = order.weight * 4;
    }
  } else {
    if (order.weight > 10) result = order.weight * 6;
    else result = order.weight * 5;
  }
  return result;
}

function calculatePrice(item: any, customer: any) {
  let price = item.basePrice;
  if (customer.isVIP && item.onSale) price *= 0.8;
  else if (customer.isVIP && !item.onSale) price *= 0.9;
  else if (!customer.isVIP && item.onSale) price *= 0.95;
  else price *= 1;
  return price;
}

// Version A: Polymorphic subclasses
class Customer { computeBilling(item: any) { return item.base; } }
class VipCustomer extends Customer { computeBilling(item: any) { return item.base * 0.9; } }
class RegularCustomer extends Customer { computeBilling(item: any) { return item.base; } }

// Version B: Centralized conditional logic
function computeBilling(customer: any, item: any) {
  if (customer.type === 'vip') return item.base * 0.9;
  if (customer.type === 'regular') return item.base;
  return item.base;
}
